AND mur.user_id = #{param.userId}
AND m.type = #{param.type}
AND m.application IN
#{app}

SELECT m.id, m.create_user_id, m.create_user_name, m.create_time, m.update_user_id, m.update_user_name, m.update_time, m.version, m.is_deleted, m.type, m.data_json, m.remark, mur.is_read FROM message m LEFT JOIN message_user_read mur on m.id = mur.message_id AND mur.is_deleted = FALSE WHERE m.is_deleted = FALSE
AND mur.user_id = #{param.userId}
AND m.type = #{param.type}
AND m.application IN
#{app}
ORDER BY m.create_time DESC limit #{param.pageSize} offset #{param.offSet}

SELECT m."type",count(*) count,max(m.create_time) latestTime FROM message m 
LEFT JOIN message_user_read mur on m.id = mur.message_id AND mur.is_deleted = FALSE WHERE m.is_deleted = FALSE 

    AND mur.user_id = #{param.userId}


    AND m.type = #{param.type}


    AND m.application IN

        #{app}


and mur.is_read = false 
GROUP BY m."type"

SELECT m.id, m.upgrade_version as upgradeVersion, m.data_json as dataJson, m.create_user_id as createUserId, m.create_user_name as createUserName, m.create_time as createTime, m.expire_time as expireTime FROM message m WHERE m.is_deleted = FALSE AND m.application = 'sysVersion'
${params.permissionSql}
ORDER BY m.create_time DESC

SELECT m.id, m.notice_title, m.type, m.data_json, m.create_time as noticeTime, COALESCE(mur.is_read, FALSE) as isRead FROM message m LEFT JOIN message_user_read mur on m.id = mur.message_id WHERE m.is_deleted = FALSE AND m.application = 'PC' AND mur.is_deleted = FALSE AND mur.user_id = #{userId}
AND m.id = #{params.id}
AND m.notice_title LIKE CONCAT('%', #{params.noticeTitle}, '%')
AND m.type = #{params.type}
${params.permissionSql}
ORDER BY m.create_time DESC

SELECT m.id, m.upgrade_version as upgradeVersion, m.data_json, m.create_time as noticeTime, COALESCE(mur.is_read, FALSE) as isRead FROM message m LEFT JOIN message_user_read mur on m.id = mur.message_id AND mur.is_deleted = FALSE AND mur.user_id = #{userId} WHERE m.is_deleted = FALSE AND m.application = 'sysVersion'
${params.permissionSql}
ORDER BY m.create_time DESC
